import mq3.botlib.l_memory as m
import std.string as strings
function stringsContains(text,part) return strings.indexOf(text,part,0)>=0 end function
function req(value,message) if not value then return error(7901,message) end if;return 1 end function
function main(args)
 count=0;s=m.create(1048576,true);a=m.GetMemoryDebug(s,12,"route-cache","be_aas.c",42,true);b=m.GetClearedHunkMemoryDebug(s,7,"aas-world","be_aas_main.c",9,true);count=count+req(s.numblocks==2 and s.blocks[0].handle==b,"linked newest first");count=count+req(m.MemoryByteSize(s,a,true)==32 and m.MemoryByteSize(s,b,true)==27,"header byte sizes");count=count+req(s.allocatedmemory==59 and s.totalmemorysize==99,"manager statistics");count=count+req(s.blocks[0].cleared and not s.blocks[1].cleared,"clear metadata");count=count+req(not s.actions[0].dispatched,"retail suppression");rows=m.PrintMemoryLabels(s,true);count=count+req(len(rows)==7 and stringsContains(rows[5],"aas-world"),"debug labels");count=count+req(m.FreeMemory(s,b,true) and s.numblocks==1 and s.actions[len(s.actions)-1].kind=="hunk-release","logical hunk release");count=count+req(m.FreeMemory(s,a,true) and s.numblocks==0 and s.actions[len(s.actions)-1].kind=="heap-free","heap free");count=count+req(not m.FreeMemory(s,999,true) and len(s.diagnostics)==1,"invalid free diagnostic");count=count+req(m.MemoryByteSize(s,999,true)==0 and len(s.diagnostics)==2,"invalid size diagnostic");copy=m.CopyString(s,"Ranger",true);data=m.readBytes(s,copy,0,7,true);count=count+req(decode(slice(data,0,6))=="Ranger" and data[6]==0,"copy string nul");failed=try(m.writeBytes(s,copy,7,bytes("x"),true)) is error;count=count+req(failed,"bounds checked write");m.DumpMemory(s,true);count=count+req(s.numblocks==0 and s.allocatedmemory==0 and s.totalmemorysize==0,"dump reset");native=m.create(10,false);m.GetMemory(native,1,false);count=count+req(native.actions[0].dispatched,"native host dispatch");print("PASS: "+str(count)+" native l_memory contracts");return 0
end function
